  --color-surface: #ffffff;
  --color-primary: #4f46e5;
  --color-primary-hover: #4338ca;
  --color-text: #1e1b4b;
  --color-muted: #6b7280;
  --color-border: #d1d5db;
  --color-border-focus: #4f46e5;
  --color-error: #dc2626;
  --color-error-bg: #fef2f2;
  --color-success: #16a34a;
  --radius: 10px;
  --shadow: 0 4px 24px rgba(79, 70, 229, 0.08);
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
}

.page-wrapper {
  width: 100%;
  max-width: 520px;
}

.support-header {
  text-align: center;
  margin-bottom: 2rem;
}

.support-header .badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #ede9fe;
  color: var(--color-primary);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 999px;
  margin-bottom: 1rem;
}

.support-header h1 {
  font-size: 1.875rem;
  font-weight: 700;
  color: var(--color-text);
  line-height: 1.2;
  margin-bottom: 0.5rem;
}

.support-header p {
  color: var(--color-muted);
  font-size: 0.95rem;
  line-height: 1.6;
}

.card {
  background: var(--color-surface);
  border-radius: 16px;
  box-shadow: var(--shadow);
  padding: 2.5rem 2rem;
  border: 1px solid #ede9fe;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 1.25rem;
}

.form-field:last-of-type {
  margin-bottom: 0;
}

label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text);
  display: flex;
  align-items: center;
  gap: 4px;
}

label .required-star {
  color: var(--color-error);
  font-size: 0.8rem;
}

label .optional-tag {
  font-size: 0.75rem;
  font-weight: 400;
  color: var(--color-muted);
  margin-left: 2px;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
  width: 100%;
  padding: 0.65rem 0.9rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius);
  font-size: 0.95rem;
  color: var(--color-text);
  background: #fafafa;
  transition: border-color 0.18s, box-shadow 0.18s, background 0.18s;
  outline: none;
  font-family: inherit;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus {
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.12);
  background: #fff;
}

input.error {
  border-color: var(--color-error);
  background: var(--color-error-bg);
}

input.error:focus {
  box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.1);
}

.helper-text {
  font-size: 0.78rem;
  color: var(--color-muted);
  line-height: 1.4;
  display: flex;
  align-items: center;
  gap: 5px;
}

.helper-text svg {
  flex-shrink: 0;
  opacity: 0.65;
}

.validation-message {
  font-size: 0.8rem;
  color: var(--color-error);
  display: none;
  align-items: center;
  gap: 4px;
}

.validation-message.visible {
  display: flex;
}

.form-actions {
  margin-top: 1.75rem;
}

.btn-submit {
  width: 100%;
  padding: 0.75rem 1.5rem;
  background: var(--color-primary);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: background 0.18s, transform 0.12s, box-shadow 0.18s;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  box-shadow: 0 2px 8px rgba(79, 70, 229, 0.25);
}

.btn-submit:hover {
  background: var(--color-primary-hover);
  box-shadow: 0 4px 16px rgba(79, 70, 229, 0.35);
}

.btn-submit:active {
  transform: scale(0.98);
}

.btn-submit:disabled {
  opacity: 0.65;
  cursor: not-allowed;
  transform: none;
}

.success-banner {
  display: none;
  background: #f0fdf4;
  border: 1.5px solid #bbf7d0;
  border-radius: var(--radius);
  padding: 1rem 1.25rem;
  margin-top: 1.25rem;
  color: var(--color-success);
  font-size: 0.9rem;
  font-weight: 500;
  align-items: center;
  gap: 10px;
}

.success-banner.visible {
  display: flex;
}

@media (max-width: 480px) {
  .card {
    padding: 1.75rem 1.25rem;
  }

  .support-header h1 {
    font-size: 1.5rem;
  }
}
