AssistantMessageToolRequest(name='create', tool_call_id='tooluse_3Me7HaSWCBzyWxsTmJysMl', arguments={'file_text': '(() => {
  const form = document.getElementById('contact-form');
  const successBanner = document.getElementById('success-banner');

  const fields = {
    fullName: {
      input: document.getElementById('full-name'),
      error: document.getElementById('full-name-error'),
      validate(value) {
        if (!value.trim()) return 'Full name is required.';
        if (value.trim().length < 2) return 'Please enter your full name.';
        return null;
      },
    },
    email: {
      input: document.getElementById('email'),
      error: document.getElementById('email-error'),
      validate(value) {
        if (!value.trim()) return 'Email address is required.';
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim()))
          return 'Please enter a valid email address.';
        return null;
      },
    },
    phone: {
      input: document.getElementById('phone'),
      error: document.getElementById('phone-error'),
      validate(value) {
        if (!value.trim()) return null; // optional
        if (!/^\+?[\d\s\-().]{7,20}$/.test(value.trim()))
          return 'Please enter a valid phone number.';
        return null;
      },
    },
  };

  function showError(field, message) {
    field.input.classList.add('error');
    field.error.textContent = message;
    field.error.classList.add('visible');
    field.input.setAttribute('aria-invalid', 'true');
  }

  function clearError(field) {
    field.input.classList.remove('error');
    field.error.textContent = '';
    field.error.classList.remove('visible');
    field.input.setAttribute('aria-invalid', 'false');
  }

  // Validate on blur (after user leaves a field)
  Object.values(fields).forEach((field) => {
    field.input.addEventListener('blur', () => {
      const error = field.validate(field.input.value);
      if (error) {
        showError(field, error);
      } else {
        clearError(field);
      }
    });

    // Clear error as user types after first interaction
    field.input.addEventListener('input', () => {
      if (field.input.classList.contains('error')) {
        const error = field.validate(field.input.value);
        if (!error) clearError(field);
      }
    });
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    let valid = true;

    Object.values(fields).forEach((field) => {
      const error = field.validate(field.input.value);
      if (error) {
        showError(field, error);
        valid = false;
      } else {
        clearError(field);
      }
    });

    if (!valid) {
      // Focus the first invalid field
      const first = Object.values(fields).find((f) =>
        f.input.classList.contains('error')
      );
      if (first) first.input.focus();
      return;
    }

    // Simulate submission
    const btn = form.querySelector('.btn-submit');
    btn.disabled = true;
    btn.textContent = 'Sending…';

    setTimeout(() => {
      btn.disabled = false;
      btn.innerHTML = `
        <svg width="16" height="16" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2.5">
          <path stroke-linecap="round" stroke-linejoin="round" d="M5 13l4 4L19 7"/>
        </svg>
        Send Message`;
      form.reset();
      Object.values(fields).forEach(clearError);
      successBanner.classList.add('visible');
      successBanner.scrollIntoView({ behavior: 'smooth', block: 'nearest' });

      setTimeout(() => {
        successBanner.classList.remove('visible');
        btn.textContent = 'Send Message';
      }, 5000);
    }, 900);
  });
})();
